package main

import "fmt"

func main() {
	fmt.Println("=== 1. Array ===")
	var arr [3]string
	arr[0] = "Go"
	arr[1] = "Rust"
	arr[2] = "Zig"
	fmt.Printf("Array: %v, Panjang: %d\n", arr, len(arr))

	fmt.Println("\n=== 2. Slice ===")
	// Slice deklarasi
	slice := []string{"Backend", "Frontend"}

	// Menambahkan elemen dinamis (append)
	slice = append(slice, "DevOps")
	fmt.Printf("Slice: %v, Panjang: %d, Kapasitas: %d\n", slice, len(slice), cap(slice))

	fmt.Println("\n=== 3. Slice dengan Make (Best Practice) ===")
	// Membuat slice dengan kapasitas awal untuk mencegah realokasi memori berulang
	buffer := make([]int, 0, 10)
	for i := 1; i <= 5; i++ {
		buffer = append(buffer, i*10)
	}
	fmt.Printf("Buffer: %v, Len: %d, Cap: %d\n", buffer, len(buffer), cap(buffer))

	fmt.Println("\n=== 4. Slicing ===")
	// Memotong elemen (start_index : end_index eksklusif)
	bagian := buffer[1:4] 
	fmt.Println("Elemen indeks 1 s/d 3:", bagian)
}
